import React, { useState } from 'react';
import { Navbar, Nav, Container } from 'react-bootstrap';
import { CiMail } from "react-icons/ci";
import "./Navbar.css";
import PdfViewer from '../pdfViewer/PdfViewer';
import ResumePDF from "../../asset/pdf/resume.pdf";
import PortfolioPDF from "../../asset/pdf/portfolio.pdf";
import logo from "../../asset/img/SiteLogo.png";


const NavigationBar = () => {
  const [showPdf, setShowPdf] = useState(false);
  const [pdfFile, setPdfFile] = useState(null);

  return (
    <>
    <Navbar className="custom-navbar" bg="dark" variant="dark" expand="lg" fixed="top">
      <Container>
        <Navbar.Brand href="/" className="navbar-brand">
        <img src={logo} alt="Site Logo" className="navbar-brand-logo" />
          광훈's Devfolio
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" />
        <Navbar.Collapse id="basic-navbar-nav"  className="navbar-collapse">
          <Nav className="ms-auto navbar-links">
            <Nav.Link href="#home">About me</Nav.Link>
            <Nav.Link href="#projects">Projects</Nav.Link>
            <Nav.Link href="#tech-stack">Tech Stack</Nav.Link>
            <Nav.Link href="#contact">Contact</Nav.Link>
            <Nav.Link onClick={() => {setPdfFile(ResumePDF); setShowPdf(true);}}>Resume</Nav.Link>
            <Nav.Link onClick={() => {setPdfFile(PortfolioPDF); setShowPdf(true);}}>Portfolio</Nav.Link>
          </Nav>
          <a href="mailto:hosookkh@gmail.com" className="navbar-mail">
            <CiMail size={30} className="mail-icon" />
          </a>
        </Navbar.Collapse>
      </Container>
    </Navbar>

    {pdfFile && (
      <PdfViewer pdfFile={pdfFile} show={showPdf} handleClose={() => setShowPdf(false)} />
    )}
  </>
  );
};

export default NavigationBar;