import React, { useState, useEffect } from "react";
import { projects } from "../../data/portfolio";
import { Card, Col, Container, Row } from "react-bootstrap";
import { IoLogoGithub, IoLogoYoutube } from "react-icons/io5";
import { FaRegFilePdf } from "react-icons/fa6";
import MarkdownViewer from '../markdownViewer/MarkdownViewer';
import PdfViewer from '../pdfViewer/PdfViewer';
import "./Projects.css";

import ECRPDF from "../../asset/pdf/ECRPDF.pdf";
import HealScopePDF from "../../asset/pdf/HealScopePDF.pdf";
import DECOBETPDF from "../../asset/pdf/DECOBETPDF.pdf";
import DECOBETV2PDF from "../../asset/pdf/DECOBETV2PDF.pdf";

const pdfFiles = {
  ECRPDF,
  HealScopePDF,
  DECOBETPDF,
  DECOBETV2PDF,
};

const Projects = () => {
  const [showReadme, setShowReadme] = useState(false);
  const [readmeFile, setReadmeFile] = useState("");
  const [showPdf, setShowPdf] = useState(false);
  const [pdfFile, setPdfFile] = useState(null);

  useEffect(() => {
    if (!pdfFile) return;
  }, [pdfFile]);

  useEffect(() => {
    if (!readmeFile) return;
  }, [readmeFile]);

  return (
    <Container id="projects" className="projects-container">
      <h2 className="section-title">Projects</h2>
      <Row className="card-container">
        {projects.personalProjects.map((project, index) => (
          <Col key={index} md={4} className="mb-4">
            <Card className="project-card">
              <Card.Img 
                variant="top" 
                src={require(`../../asset/img/${project.src}`)} 
                alt={project.title} 
                className="project-image"
                onClick={() => {
                  setReadmeFile(require(`../../asset/md/${project.readme}`));
                  setShowReadme(true);
                }} 
              />
              <Card.Body>
                <Card.Title className="project-title">{project.title}</Card.Title>
                <Card.Text className="project-short">{project.short}</Card.Text>
                <Card.Text className="project-description">{project.description}</Card.Text>
                
                {project.techDetail.map((td, idx) => (
                  <Card.Text key={idx} className="project-tech-detail">
                    {td.split(/(\*\*.*?\*\*)/g).map((part, subIdx) =>
                      part.startsWith("**") && part.endsWith("**") ? (
                        <b key={subIdx}>{part.replace(/\*\*/g, "")}</b>
                      ) : (
                        part
                      )
                    )}
                  </Card.Text>
                ))}
                <div className="project-footer">
                  <div className="project-technologies">
                    {project.technologies.map((badge, idx) => (
                      <img key={idx} src={badge} alt="tech-badge" className="tech-badge" />
                    ))}
                  </div>
                  <div className="project-links">
                    <a href={project.github} target="_blank" rel="nooperner noreferrer" className="project-icon">
                      <IoLogoGithub size={30} style={{ color: "black" }} />
                    </a>
                    <FaRegFilePdf
                      size={30}
                      onClick={() => {
                        setPdfFile(pdfFiles[project.pdf]);
                        setShowPdf(true);
                      }}
                      style={{ cursor: "pointer" }}
                    />
                    <a href={project.demo} target="_blank" rel="nooperner noreferrer" className="project-icon">
                      <IoLogoYoutube size={30} style={{ color: "red" }} />
                    </a>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
      {pdfFile && (
        <PdfViewer pdfFile={pdfFile} show={showPdf} handleClose={() => setShowPdf(false)} />
      )}
      {readmeFile && (
        <MarkdownViewer readmeFile={readmeFile} show={showReadme} handleClose={() => setShowReadme(false)} />
      )}
    </Container>
  )
}

export default Projects;