import React, { useState, useEffect, useRef } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeRaw from "rehype-raw";
import mermaid from "mermaid";
import { Modal, Button } from "react-bootstrap";

const MarkdownViewer = ({ show, handleClose, readmeFile }) => {
  const [markdown, setMarkdown] = useState("");
  const mermaidRef = useRef(null);

  useEffect(() => {
    if (show && readmeFile) {
      fetch(readmeFile)
        .then((res) => res.text())
        .then(setMarkdown)
        .catch((err) => console.error("Failed to load markdown file:", err));
    }
  }, [show, readmeFile]);

  useEffect(() => {
    if (show && mermaidRef.current) {
      mermaid.initialize({ startOnLoad: true });
      mermaid.run();
    }
  }, [markdown, show]);

  return (
    <Modal show={show} onHide={handleClose} size="lg">
      <Modal.Header closeButton>
        <Modal.Title>프로젝트 README</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <div ref={mermaidRef}>
          <ReactMarkdown 
            remarkPlugins={[remarkGfm]} 
            rehypePlugins={[rehypeRaw]}  // HTML 태그 렌더링 활성화
            components={{
              code({ node, inline, className, children, ...props }) {
                const match = /language-(\w+)/.exec(className || "");
                if (match?.[1] === "mermaid") {
                  return (
                    <div className="mermaid">
                      {children}
                    </div>
                  );
                }
                return <code className={className} {...props}>{children}</code>;
              }
            }}
          >
            {markdown}
          </ReactMarkdown>
        </div>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="secondary" onClick={handleClose}>
          닫기
        </Button>
      </Modal.Footer>
    </Modal>
  )
}
export default MarkdownViewer;